// Kalam as pen strokes, for notes that write themselves out (see HandNote).
// Generated by Tegaki's font generator, which the tegaki package doesn't ship
// a copy of for this font:
//   bun start generate "Kalam" -o <folder>   (github.com/gkurt/tegaki, packages/generator)
// Only the two font URLs differ from the generated file, so the bundler finds them.
import glyphData from './glyphData.json';
import glyphDataById from './glyphDataById.json';

const fontUrl = new URL('./kalam-3dc76002.ttf', import.meta.url).href;
const fullFontUrl = new URL('./kalam.ttf', import.meta.url).href;

const bundle = {
  version: 1,
  family: 'Kalam Tegaki 3dc76002',
  fullFamily: 'Kalam',
  lineCap: 'round',
  fontUrl,
  fullFontUrl,
  fontFaceCSS: `@font-face { font-family: 'Kalam Tegaki 3dc76002'; src: url(${fontUrl}); } @font-face { font-family: 'Kalam'; src: url(${fullFontUrl}); }`,
  unitsPerEm: 1000,
  ascender: 1063,
  descender: -531,
  glyphData,
  glyphDataById,
  features: ["liga"],
} as const;

export default bundle;
